equation_logic_text:
var calc_output = [];

// CDR variables
var bp = parseFloat(bp)
var o2 = parseFloat(o2)
var rr = parseFloat(rr)
var pulse = parseFloat(pulse)
var dyspnea = parseFloat(dyspnea)
var hemorrhage = parseFloat(hemorrhage)

var cdr = bp + o2 + rr + pulse + dyspnea + hemorrhage

var risk

if (cdr > 0) { // CDR positive
    var ecog = parseFloat(ecog)
    var symptoms = parseFloat(symptoms)
    if (ecog == 0) {
        if (symptoms == 0) {
            risk = 'High'
        } else {
            risk = 'Intermediate'
        }
    } else if (ecog == 1) {
        if (o2 == 0) {
            risk = 'Intermediate'
        } else {
            risk = 'Intermediate'
        }
    }
} else { // CDR negative
    var tumor = parseFloat(tumor)
    var surgery = parseFloat(surgery)
    if (tumor == 0) {
        if (surgery == 1) {
            risk = 'High'
        } else {
            risk = 'Low'
        }
    } else {
        risk = 'Low'
    }
}

var comp, mort

if (risk == 'Low') {
    comp = 1.6
    mort = 1.3
} else if (risk == 'Intermediate') {
    comp = 9.4
    mort = 8.9
} else {
    comp = 30.6
    mort = 23.3
}

calc_output.push({
    name: 'mini',
    value: risk,
    value_text: 'risk',
    message: comp + '% complication rate'
});
calc_output.push({
    name: 'Risk group',
    value: risk,
    value_text: 'risk',
    message: 'EPIPHANY Index'
});
calc_output.push({
    name: 'Risk percent',
    value: comp,
    value_text: '%',
    message: 'Risk of serious complications at 15 days, including major bleeding, need for ICU admission, CPR, etc'
});
calc_output.push({
    name: 'Mortality',
    value: mort,
    value_text: '%',
    message: '30-day mortality'
});
